frappe.ui.form.on('Purchase Invoice Item', {
  item_code: function(frm, cdt, cdn) {
    var item = locals[cdt][cdn].item_code;
    frappe.call({
      method: "erpnext.stock.doctype.item.item.get_item_details",
      args: { item_code: item },
      callback: function(r) {
        if (r.message) {
          var mrp = r.message.mrp;
          if (mrp) {
            frappe.model.set_value(cdt, cdn, "mrp", mrp);
          }
        }
      }
    });
  }
});

