frappe.ui.form.on('Item', {
    validate: function(frm) {
        console.log("Disabled status: " + frm.doc.disabled);

        if (frm.doc.disabled === 0) {
            var code = frm.doc.item_code;
            
            frappe.call({
                method: "frappe.client.get_value",
                args: {
                    doctype: "Item Price",
                    filters: {
                        item_code: code,
                        price_list: "Standard Buying"
                    },
                    fieldname: ["price_list_rate", "name"]
                },
                callback: function(r) {
                    console.log("After callback function");
                    console.log("Passed to margin: " + frm.doc.t0_margin);

                    var buying_price = r.message.price_list_rate;
                    var item_price_name = r.message.name;

                    // Calculate selling prices
                    frappe.call({
                        method: "frappe.client.get_value",
                        args: {
                            doctype: "Item",
                            filters: { item_code: code },
                            fieldname: ["t0_margin", "t1_margin", "t2_margin", "t3_margin", "custom_is_price_sensitive", "custom_force_round"]
                        },
                        callback: function(s) {
                            var t0_margin = frm.doc.t0_margin;
                            var t1_margin = frm.doc.t1_margin;
                            var t2_margin = frm.doc.t2_margin;
                            var t3_margin = frm.doc.t3_margin;
                            var is_price_sensitive = s.message.custom_is_price_sensitive;
                            var force_round = s.message.custom_force_round;

                            if (t2_margin) {
                                console.log("t2_margin value found: " + t2_margin);

                                var selling_price2 = buying_price / ((100 - t2_margin) / 100);
                                var selling_price0 = buying_price / ((100 - parseFloat(t0_margin)) / 100);
                                var selling_price1 = buying_price / ((100 - parseFloat(t1_margin)) / 100);
                                var selling_price3 = buying_price / ((100 - parseFloat(t3_margin)) / 100);

                                // Apply rounding if buying price is greater than 10 or if custom_force_round is true
                                //if (selling_price2 > 10 || force_round) {
                                //    selling_price2 = Math.ceil(selling_price2);
                                //    selling_price0 = Math.ceil(selling_price0);
                                //    selling_price1 = Math.ceil(selling_price1);
                                //    selling_price3 = Math.ceil(selling_price3);

                                if (!is_price_sensitive || force_round) {
                                        selling_price2 = Math.ceil(selling_price2 / 5) * 5;
                                        selling_price0 = Math.ceil(selling_price0 / 5) * 5;
                                        selling_price1 = Math.ceil(selling_price1 / 5) * 5;
                                        selling_price3 = Math.ceil(selling_price3 / 5) * 5;
                                   // }
                                }

                                if (frm.doc.mrp > 0) {
                                    if (frm.doc.mrp <= selling_price2) selling_price2 = frm.doc.mrp -  frm.doc.mrp*(1/100);
                                    if (frm.doc.mrp <= selling_price0) selling_price0 = frm.doc.mrp - frm.doc.mrp*(1/100);
                                    if (frm.doc.mrp <= selling_price1) selling_price1 = frm.doc.mrp - frm.doc.mrp*(1/100);
                                    if (frm.doc.mrp <= selling_price3) selling_price3 = frm.doc.mrp - frm.doc.mrp*(1/100);
                                }
                                

                                // Update prices in Item Price doctype
                                updateItemPrice("Standard Selling", selling_price2);
                                updateItemPrice("T0 Price List", selling_price0);
                                updateItemPrice("T1 Price List", selling_price1);
                                updateItemPrice("T3 Price List", selling_price3);
                            } else {
                                console.log("No t2_margin value found for item code: " + code);
                            }
                        }
                    });
                }
            });

            function updateItemPrice(price_list, price) {
                frappe.call({
                    method: "frappe.client.get_value",
                    args: {
                        doctype: "Item Price",
                        filters: {
                            item_code: code,
                            price_list: price_list
                        },
                        fieldname: ["price_list_rate", "name"]
                    },
                    callback: function(s) {
                        var selling_price_list_name = s.message.name;

                        if (selling_price_list_name) {
                            frappe.call({
                                method: "frappe.client.set_value",
                                args: {
                                    doctype: "Item Price",
                                    name: selling_price_list_name,
                                    fieldname: "price_list_rate",
                                    value: price
                                },
                                callback: function(response) {
                                    console.log("Price updated successfully for " + price_list);
                                },
                                error: function(response) {
                                    console.error("Error updating price for " + price_list + ": ", response);
                                }
                            });
                        } else {
                            frappe.model.with_doctype("Item Price", function() {
                                var item_price = frappe.model.get_new_doc("Item Price");
                                item_price.item_code = code;
                                item_price.price_list = price_list;
                                item_price.price_list_rate = price;
                                frappe.db.insert(item_price);
                            });
                        }
                    }
                });
            }
        }
    }
});

