frappe.ui.form.on('POS Profile User', {
    restaurant_permission(frm, cdt, cdn) {
        if(cdn.includes('new')){
            frappe.show_alert(__("Save the record before assigning permissions"));
            return;
        }

        new DeskForm({
            form_name: 'Restaurant Permission Manage',
            doc_name: cdn,
            callback: (self) => {
                self.hide();
            },
            title: __(`Room Access`),
            field_properties: {
                pos_profile_user: {
                  value: cdn  
                },
                'restaurant_permission.room': {
                    "get_query": () => {
                        return {
                            filters: [
                    			['type', '=', 'Room']
                    		]
                        }
                    }
                }
            }
        });
    }
});

frappe.ui.form.on("Purchase Invoice", "on_submit", function(frm) {
    console.log("begin ");
    var user = frappe.session.user; // get current user
    console.log("Before loop");

    if ((frm.doc.supplier !== "Hardware store" && frm.doc.supplier !== "Fix & Build Karanthad")) {
        $.each(frm.doc.items || [], function(i, v) {
            console.log("Supplier: " + frm.doc.supplier);

            frappe.call({
                method: "frappe.client.get_value",
                args: {
                    doctype: "Item Price",
                    filters: {
                        item_code: v.item_code,
                        price_list: "Standard Buying"
                    },
                    fieldname: ["price_list_rate", "name"]
                },
                callback: function(r) {
                    if (r && r.message && r.message.price_list_rate) {
                        var buying_price = r.message.price_list_rate;
                        var buying_price_list_name = r.message.name;
                        
                        // Fetch item details including custom_force_round
                        frappe.call({
                            method: "frappe.client.get_value",
                            args: {
                                doctype: "Item",
                                filters: {
                                    item_code: v.item_code
                                },
                                fieldname: ["t2_margin", "t0_margin", "t1_margin", "t3_margin", "loose_margin", "custom_is_price_sensitive", "custom_force_round"]
                            },
                            callback: function(s) {
                                var t2_margin = s.message.t2_margin;
                                var t0_margin = s.message.t0_margin;
                                var t1_margin = s.message.t1_margin;
                                var t3_margin = s.message.t3_margin;
                                var is_price_sensitive = s.message.custom_is_price_sensitive;
                                var force_round = s.message.custom_force_round;

                                // Update buying price with rounded value if greater than 10
                                if (v.rate > 10 || force_round) {
                                    v.rate = Math.ceil(v.rate);
                                }
                                frappe.db.set_value("Item Price", buying_price_list_name, "price_list_rate", v.rate);

                                // Calculating selling prices
                                if (t2_margin) {
                                    var selling_price2 = v.rate / ((100 - parseFloat(t2_margin)) / 100);
                                    var selling_price0 = v.rate / ((100 - parseFloat(t0_margin)) / 100);
                                    var selling_price1 = v.rate / ((100 - parseFloat(t1_margin)) / 100);
                                    var selling_price3 = v.rate / ((100 - parseFloat(t3_margin)) / 100);
                                   
                                    // Apply rounding if force_round is true or standard buying price is greater than or equal to 10
                                    if (force_round || (!is_price_sensitive && selling_price2 >= 10)) {
                                        selling_price2 = Math.ceil(selling_price2 / 5) * 5;
                                        selling_price0 = Math.ceil(selling_price0 / 5) * 5;
                                        selling_price1 = Math.ceil(selling_price1 / 5) * 5;
                                        selling_price3 = Math.ceil(selling_price3 / 5) * 5;
                                    }

                                    // Capping selling prices to MRP if specified
                                    if (v.mrp > 0) {
                                        selling_price2 = Math.min(selling_price2, v.mrp);
                                        selling_price0 = Math.min(selling_price0, v.mrp);
                                        selling_price1 = Math.min(selling_price1, v.mrp);
                                        selling_price3 = Math.min(selling_price3, v.mrp);
                                    }

                                    // Setting values in Item Price doctype
                                    function setItemPrice(priceList, price) {
                                        frappe.call({
                                            method: "frappe.client.get_value",
                                            args: {
                                                doctype: "Item Price",
                                                filters: { item_code: v.item_code, price_list: priceList },
                                                fieldname: ["price_list_rate", "name"]
                                            },
                                            callback: function(res) {
                                                if (res.message && res.message.name) {
                                                    frappe.db.set_value("Item Price", res.message.name, "price_list_rate", price);
                                                } else {
                                                    frappe.model.with_doctype("Item Price", function() {
                                                        var item_price = frappe.model.get_new_doc("Item Price");
                                                        item_price.item_code = v.item_code;
                                                        item_price.price_list = priceList;
                                                        item_price.price_list_rate = price;
