frappe.ui.form.on('Item', {
    validate: function(frm) {
        if (frm.doc.disabled == 0) {
            var code = frm.doc.item_code;
            frappe.call({
                method: "frappe.client.get_value",
                args: {
                    doctype: "Item Price",
                    filters: {
                        item_code: code,
                        price_list: "Standard Buying"
                    },
                    fieldname: ["price_list_rate", "name"]
                },
                callback: function(r) {
                    if (r.message) {
                        var buying_price = r.message.price_list_rate;
                        var buying_price_list_name = r.message.name;

                        if (buying_price > 10) {
                            buying_price = Math.ceil(buying_price);
                        }

                        var margins = ["t0_margin", "t1_margin", "t2_margin", "t3_margin", "loose_margin"];
                        var selling_prices = {};

                        margins.forEach(function(margin) {
                            if (frm.doc[margin]) {
                                selling_prices[margin] = buying_price / ((100 - parseFloat(frm.doc[margin])) / 100);
                                if (selling_prices[margin] > 10) {
                                    selling_prices[margin] = Math.ceil(selling_prices[margin]);
                                }
                                if (frm.doc.mrp > 0 && frm.doc.mrp < selling_prices[margin]) {
                                    selling_prices[margin] = frm.doc.mrp - 1;
                                }
                            }
                        });

                        var price_lists = {
                            "Standard Selling": selling_prices.t2_margin,
                            "T0 Price List": selling_prices.t0_margin,
                            "T1 Price List": selling_prices.t1_margin,
                            "T3 Price List": selling_prices.t3_margin
                        };

                        Object.keys(price_lists).forEach(function(price_list) {
                            if (price_lists[price_list]) {
                                frappe.call({
                                    method: "frappe.client.get_value",
                                    args: {
                                        doctype: "Item Price",
                                        filters: {
                                            item_code: code,
                                            price_list: price_list
                                        },
                                        fieldname: ["price_list_rate", "name"]
                                    },
                                    callback: function(s) {
                                        if (s.message) {
                                            frappe.db.set_value("Item Price", s.message.name, "price_list_rate", price_lists[price_list]);
                                        } else {
                                            frappe.model.with_doctype("Item Price", function() {
                                                var item_price = frappe.model.get_new_doc("Item Price");
                                                item_price.item_code = code;
                                                item_price.price_list = price_list;
                                                item_price.price_list_rate = price_lists[price_list];
                                                frappe.db.insert(item_price);
                                            });
                                        }
                                    }
                                });
                            }
                        });
                    }
                }
            });
        }
    }
});

