function validate_due_date(frm) {
    let today = frappe.datetime.get_today();
    let max_date = frappe.datetime.add_days(today, 15);

    if (!frm.doc.custom_new_due_date) {
        // Set 'custom_new_due_date' to the value of 'due_date' if it's empty
        frm.set_value('custom_new_due_date', frm.doc.due_date);
    }

    // Validate that 'custom_new_due_date' is not less than today's date or more than 60 days from today
    if (frm.doc.custom_new_due_date < today) {
        frappe.msgprint(__('The new due date cannot be before today.'));
        frappe.validated = false;
    } else if (frm.doc.custom_new_due_date > max_date) {
        frappe.msgprint(__('The new due date cannot be more than 15 days from today.')); 
        frappe.validated = false;
    }
}

