                price_list: price_list,
                item_code: ['in', frm.doc.items.map(item => item.item_code)]
            },
            fields: ['item_code', 'price_list_rate']
        },
        callback: function(response) {
            if (response.message) {
                let total_amount = 0;

                // Create a dictionary for easy price lookup
                const item_prices = {};
                response.message.forEach(price => {
                    item_prices[price.item_code] = price.price_list_rate;
                });

                // Calculate total based on the selected price list with UOM conversion
                frm.doc.items.forEach(item => {
                    let rate = item_prices[item.item_code] || item.rate;  // Use the price list rate or default to existing rate
                    let conversion_factor = item.conversion_factor || 1;  // Default conversion factor is 1 if not specified
                    let adjusted_rate = rate * conversion_factor;  // Adjust rate according to conversion factor
                    total_amount += adjusted_rate * item.qty;
                });

                // Display the total immediately
                frappe.msgprint(__('Total Amount with Selected Price List: ') + format_currency(total_amount, frm.doc.currency));
            } else {
                frappe.msgprint(__('No prices found for the selected Price List.'));
