function calculate_total_with_price_list(frm, price_list) {
    frappe.call({
        method: 'frappe.client.get_list',
        args: {
            doctype: 'Item Price',
            filters: {
                price_list: price_list,
                item_code: ['in', frm.doc.items.map(item => item.item_code)]
            },
            fields: ['item_code', 'price_list_rate']
        },
        callback: function(response) {
            if (response.message) {
                let total_amount = 0;

                // Create a dictionary for easy price lookup
                const item_prices = {};
                response.message.forEach(price => {
                    item_prices[price.item_code] = price.price_list_rate;
                });

                // Calculate total based on the selected price list, accurately handling UOM conversion
                frm.doc.items.forEach(item => {
                    let rate = item_prices[item.item_code] || item.rate;  // Use the price list rate or existing rate
                    let conversion_factor = item.conversion_factor || 1;  // Default to 1 if no conversion factor is set

                    if (rate > 0) {
                        // Adjust the rate by multiplying by the conversion factor for correct UOM conversion
                        let adjusted_rate = rate * conversion_factor;
                        total_amount += adjusted_rate * item.qty;
                    } else {
                        // If no rate in price list, add existing rate directly
                        total_amount += item.rate * item.qty;
                    }
                });

                // Display the total immediately
                frappe.msgprint(__('Total Amount with Selected Price List: ') + format_currency(total_amount, frm.doc.currency));
            } else {
                frappe.msgprint(__('No prices found for the selected Price List.'));
            }
        }
    });
}

