async function calculate_and_log_profit_for_pos(frm) {
    let total_paid_amount = frm.doc.paid_amount;
    let total_buying_cost = 0;

    frappe.msgprint(`Starting profit calculation for Invoice ${frm.doc.name}. Paid Amount: ${total_paid_amount}`);

    for (const item of frm.doc.items) {
        let buying_price = await get_buying_price(item.item_code);
        let conversion_factor = item.conversion_factor || 1;
        let qty = item.qty;

        // If buying price is zero or not found, use the selling price as a fallback
        let adjusted_buying_price = buying_price > 0 ? buying_price * conversion_factor : item.rate * conversion_factor;
        total_buying_cost += adjusted_buying_price * qty;

        frappe.msgprint(`Item ${item.item_code}: Effective Buying Price: ${adjusted_buying_price || 0} (Used Selling Price as Buying Equivalent if Buying Price is Zero), Quantity: ${qty}, Updated Total Buying Cost: ${total_buying_cost}`);
    }

    // After all items are processed, calculate and log the total profit
    let total_profit = total_paid_amount - total_buying_cost;
    frappe.msgprint(`Final Profit Calculation for Invoice ${frm.doc.name}: Total Paid Amount: ${total_paid_amount}, Total Buying Cost: ${total_buying_cost}, Total Profit: ${total_profit}`);

    // Insert a single entry into the Sales Profit Log for the entire invoice
    frappe.call({
        method: 'frappe.client.insert',
        args: {
            doc: {
                doctype: 'Sales Profit Log',
                sales_invoice: frm.doc.name,
                total_payment_made: total_paid_amount,
                sum_of_buying_prices: total_buying_cost,
                profit: total_profit,
                date: `${frm.doc.posting_date} ${frm.doc.posting_time}` // Combine date and time
            }
        },
        callback: function(response) {
            if (response && response.message) {
                frappe.msgprint("Profit log entry created successfully.");
            } else {
                frappe.msgprint("Failed to create profit log entry.");
            }
        }
    });
}

function get_buying_price(item_code) {
    return new Promise((resolve) => {
        frappe.call({
            method: 'frappe.client.get_value',
            args: {
                doctype: 'Item Price',
                filters: {
                    price_list: 'Standard Buying',
                    item_code: item_code
                },
                fieldname: 'price_list_rate'
            },
            callback: function(response) {
                let buying_price = response.message && response.message.price_list_rate ? response.message.price_list_rate : 0;
                resolve(buying_price);
            }
        });
    });
}

function delete_profit_log_entry(frm) {
    frappe.call({
        method: 'frappe.client.delete',
        args: {
            doctype: 'Sales Profit Log',
            filters: { sales_invoice: frm.doc.name }
        },
        callback: function(response) {
            if (response && response.message) {
                frappe.msgprint(`Profit log entry for Invoice ${frm.doc.name} has been deleted upon cancellation.`);
            } else {
                frappe.msgprint(`Failed to delete profit log entry for Invoice ${frm.doc.name}.`);
            }
        }
    });
}

