        // Attach a button dynamically to the item details view
        frm.page.add_action_item(__('View Item Location'), async function() {
            const selected_item_code = frm.selected_item_code; // Replace this with the actual selected item code
            const current_company = frappe.defaults.get_user_default("Company");

            if (!selected_item_code || !current_company) {
                frappe.msgprint(__('Select an item and ensure the company is set.'));
                return;
            }

            // Call your custom method to fetch the location
            frappe.call({
                method: 'posawesome_customizations.api.get_item_location',
                args: {
                    item_code: selected_item_code,
                    company: current_company,
                },
                callback: function(response) {
                    if (response.message) {
                        frappe.msgprint({
                            title: __('Item Location'),
                            message: response.message,
                            indicator: 'green',
                        });
                    } else {
                        frappe.msgprint(__('No location found for the selected item.'));
                    }
                },
            });
        });
    },
});

