document.addEventListener('DOMContentLoaded', function() {
    // Main function
    function initPurchaseInvoiceOption() {
        try {
            const container = findSetNameFromContainer();
            if (!container) return;
            
            const newOption = createPurchaseInvoiceOption();
            container.appendChild(newOption);
            
            setupEventListeners(newOption);
        } catch (error) {
            console.error("Error adding Purchase Invoice option:", error);
        }
    }

    // Helper functions
    function findSetNameFromContainer() {
        const containers = [
            'div:contains("Set Name From")',
            'div:contains("Set Name From:")',
            '.source-document-options',
            '.doc-source-options'
        ];
        
        for (const selector of containers) {
            const container = document.querySelector(selector);
            if (container) return container;
        }
        return null;
    }

    function createPurchaseInvoiceOption() {
        const option = document.createElement('div');
        option.className = 'source-option';
        option.innerHTML = `
            <input type="radio" id="from_purchase_invoice" name="source_document" value="Purchase Invoice">
            <label for="from_purchase_invoice">Purchase Invoice</label>
        `;
        return option;
    }

    function setupEventListeners(optionElement) {
        const radioBtn = optionElement.querySelector('input[type="radio"]');
        radioBtn.addEventListener('change', async function() {
            if (this.checked) {
                try {
                    const piNumber = await showPurchaseInvoiceDialog();
                    if (piNumber) {
                        const piData = await fetchPurchaseInvoiceData(piNumber);
                        populateSalesInvoiceItems(piData);
                    }
                } catch (error) {
                    showError("Failed to load purchase invoice: " + error.message);
                }
            }
        });
    }

    // Dialog and data functions
    function showPurchaseInvoiceDialog() {
        return new Promise((resolve) => {
            // Replace with your preferred dialog implementation
            const piNumber = prompt("Enter Purchase Invoice Number:");
            resolve(piNumber);
        });
    }

    async function fetchPurchaseInvoiceData(piNumber) {
        // Replace with actual API call
        console.log("Fetching PI:", piNumber);
        // return await fetch(`/api/purchase-invoices/${piNumber}`).then(r => r.json());
        
        // Mock response
        return {
            items: [
                { item_code: "PUR-ITEM1", qty: 2, rate: 15.50, description: "PVC Pipe 20mm" },
                { item_code: "PUR-ITEM2", qty: 1, rate: 22.00, description: "PVC Bend 25mm" }
            ],
            supplier: "Sample Supplier",
            date: "2025-04-01"
        };
    }

    function populateSalesInvoiceItems(data) {
        // Implement based on your items table structure
        console.log("Populating items:", data.items);
        alert(`Ready to add ${data.items.length} items from purchase invoice`);
    }

    function showError(message) {
        console.error(message);
        alert(message);
    }

    // Initialize
    initPurchaseInvoiceOption();
});

frappe.ui.form.on('Purchase Invoice', {
