                        if (r.message && r.message.prompt) {
                            // Show company selection dialog
                            var dialog = new frappe.ui.Dialog({
                                title: r.message.prompt.title,
                                fields: r.message.prompt.fields,
                                primary_action_label: "Create Sales Invoice",
