function get_price_list_filters() {
    // Check if user has the special role
    const has_role = frappe.user.has_role("Special Price Access");

    if (has_role) {
        // User can see all price lists including T0 and Standard Buying
        return {};
    }

    // Other users → hide T0 and Standard Buying
    return {
        "name": ["not in", ["T0 Price List", "Standard Buying"]]
    };
}

frappe.ui.form.on('Sales Invoice', {
    on_submit: function(frm) {

        // 1️⃣ Check if Cash payment exists
        let cash_payment = (frm.doc.payments || []).some(p => {
            return p.mode_of_payment &&
                   p.mode_of_payment.toLowerCase().includes('cash') &&
                   flt(p.amount) > 0;
        });

        if (!cash_payment) {
            console.log("No cash payment, drawer will not open");
            return;
        }

        // 2️⃣ ESC/POS command to open cash drawer
        // Works for most Epson-compatible printers
        const openDrawerCommand = '\x1B\x70\x00\x19\xFA';

        // 3️⃣ Printer name (must match OS printer name)
        const printerName = "POS-80C";

        // 4️⃣ Connect to QZ Tray and send raw command
        frappe.ui.form.qz_connect()
            .then(() => {
                let config = qz.configs.create(printerName);
                return qz.print(config, [openDrawerCommand]);
            })
            .then(() => {
                frappe.ui.form.qz_success();
            })
            .catch(err => {
                frappe.ui.form.qz_fail(err);
            });
    }
});

frappe.ui.form.on('Purchase Invoice', {

    refresh: function(frm) {
        if (frm.doc.docstatus === 1 ) {
            frm.add_custom_button(__('Sales_Invoice'), function() {
                frappe.call({
                    method: "invoice_manager.functions.make_sales_invoice_from_purchase_invoice",
                    args: {
                        source_name: frm.doc.name
                    },
                    callback: function(r) {
                        if (!r.exc) {
                            let doc = frappe.model.sync(r.message);
                            frappe.set_route("Form", doc[0].doctype, doc[0].name);
                        }
                    }
                });
            }, __('Create'));
        }
    },

    supplier: function(frm) {
        if (frm.doc.supplier) {

            // Fetch supplier defaults
            frappe.call({
                method: "frappe.client.get",
                args: {
                    doctype: "Supplier",
                    name: frm.doc.supplier
                },
                callback: function(r) {
                    if (r.message) {

                        let supplier = r.message;

                        // Example: set price list
                        if (supplier.default_price_list) {
                            frm.set_value("buying_price_list", supplier.default_price_list);
                        }

                        // Example: set contact person (if custom field or logic exists)
                        if (supplier.default_contact) {
                            frm.set_value("contact_person", supplier.default_contact);
                        }

                        // Add more fields as needed
                    }
                }
            });

            // Optional: clear old dependent values before setting new ones
            frm.set_value("contact_person", null);
            frm.set_value("buying_price_list", null);

            frm.refresh_fields();
        }
    }
});

frappe.ui.form.on('Sales Invoice', {

    customer: function(frm) {
        if (frm.doc.customer) {

            frm.set_value("selling_price_list", null);
            frm.set_value("customer_address", null);
        

            frappe.call({
                method: "frappe.client.get",
                args: {
                    doctype: "Customer",
                    name: frm.doc.customer
                },
                callback: function(r) {
                    if (r.message) {

                        let customer = r.message;

                        // Price List
                        if (customer.default_price_list) {
                            frm.set_value("selling_price_list", customer.default_price_list);
                        }

                        // Address
                        if (customer.customer_primary_address) {
                            frm.set_value("customer_address", customer.customer_primary_address);
                        }

                        // Payment Terms (Preferred)
                        if (customer.payment_terms) {
                            frm.set_value("payment_terms_template", customer.payment_terms);
                            frm.trigger("payment_terms_template");
                        } 
                        else {
                            // Fallback: Credit Days
                            let credit_days = customer.credit_days || 30;
                            let due_date = frappe.datetime.add_days(
                                frappe.datetime.get_today(),
                                credit_days
                            );
                            frm.set_value("due_date", due_date);
                        }

                        frm.refresh_fields();
                    }
                }
            });
        }
    },

  

});
